struct Ref:H8SEmulator{void history(int r,int w){lastread=r;lastwrite=w;}};
struct Event{uint64_t at;uint32_t addr;uint8_t value;bool write;};
static bool mapped(uint32_t a){return (a>=0x600000&&a<0x600010)||(a>=0xc598&&a<0xc59a);}
struct RBus:H8SDevice{Ref&c;unsigned group=0;std::array<Event,16>e{};unsigned n=0;explicit RBus(Ref&v):c(v){}uint8_t read(uint32_t a)override{auto v=a==0x600004?uint8_t(group==1?16:7):c.memory[a];e[n++]={c.cycles,a,v,false};return v;}void write(uint32_t a,uint8_t v)override{e[n++]={c.cycles,a,v,true};c.memory[a]=v;if(a==0x600000&&v==8)group=1;if(a==0x60000e)group=2;}};
struct NBus:kstation::ControllerResourceBus{unsigned group=0;bool enabled=false;std::array<Event,16>e{};unsigned n=0;bool mapped(uint32_t a)const override{return ::mapped(a);}uint8_t read(uint32_t a)override{auto v=a==0x600004?uint8_t(group==1?16:7):state_->memory[a];if(enabled)e[n++]={state_->cycles,a,v,false};return v;}void write(uint32_t a,uint8_t v)override{if(enabled)e[n++]={state_->cycles,a,v,true};state_->memory[a]=v;if(a==0x600000&&v==8)group=1;if(a==0x60000e)group=2;}};
int main(int argc,char**argv){if(argc!=2)return 77;std::ifstream f(argv[1],std::ios::binary);std::vector<uint8_t>rom{std::istreambuf_iterator<char>(f),{}};if(rom.size()!=49728)return 1;auto c=std::make_unique<Ref>();auto d=std::make_unique<kstation::ControllerDeviceState>();c->loadmem(rom.data(),rom.size(),0);d->loadMemory(rom.data(),rom.size(),0);d->loadMemory(rom.data(),rom.size(),0x400000);RBus x(*c);NBus y;c->memmap(&x,0x600000,16);c->memmap(&x,0xc598,2);d->attachBus(&y);kstation::ControllerInterruptRuntime irq;kstation::ControllerDspTransferRuntime dsp;kstation::ControllerStartupVolumeRuntime vol;if(!irq.bindVerifiedFirmware(*d,rom.data(),rom.size())||!dsp.bindVerifiedFirmware(*d,rom.data(),rom.size())||!vol.bindBootResources(*d,rom.data(),rom.size())||!vol.bindMirroredFirmware(*d,rom.data(),rom.size()))return 2;y.enabled=true;uint64_t graphs=0,phases=0,events=0,shorts=0,writes=0;for(unsigned value=0;value<256;++value)for(unsigned flags:{0u,0x80u}){irq.reset();dsp.reset();vol.reset();irq.setMask(flags?kstation::ControllerInterruptRuntime::Mask::Disabled:kstation::ControllerInterruptRuntime::Mask::Enabled);x.group=y.group=0;for(unsigned i=0;i<16;++i)c->memory[0x600000+i]=d->memory[0x600000+i]=0;c->memory[0xc598]=d->memory[0xc598]=0xff;c->memory[0xc599]=d->memory[0xc599]=0xff;c->pc=c->makepc(0x403c);c->setSP(0xffff10);for(unsigned i=0;i<4;++i)c->memory[0xffff10+i]=uint8_t(0x7000u>>(8*(3-i)));c->reg32(1)=int32_t(0x9a6c1234);c->reg8(6)=int8_t(value);c->ccr=uint8_t(flags);c->pending_irqs=d->pendingIrqs=0;c->pending_irqs_high=d->pendingIrqsHigh=0;c->interruptMode2=d->interruptMode2=false;c->cycles=d->cycles=100000;c->history(-1,-1);d->lastRead=d->lastWrite=-1;if(!vol.start(uint8_t(value)))return 3;for(unsigned k=0;vol.active();++k){if(k>10000)return 4;auto at=uint32_t(c->getPC());x.n=y.n=0;auto cost=vol.nextClocks(*d,irq,dsp);if(!cost)return 5;for(unsigned b=0;b<cost;++b){auto before=d->cycles;auto r=vol.advanceBefore(*d,irq,dsp,b);if(r.clocks||d->cycles!=before||y.n)return 6;++shorts;}c->step();auto r=vol.advanceBefore(*d,irq,dsp,cost);if(!r.clocks||c->cycles!=d->cycles||x.n!=y.n){std::fprintf(stderr,"phase pc=%x v=%u clocks=%llu/%llu io=%u/%u\n",at,value,c->cycles,d->cycles,x.n,y.n);return 7;}for(unsigned i=0;i<x.n;++i){auto a=x.e[i],b=y.e[i];if(a.at!=b.at||a.addr!=b.addr||a.value!=b.value||a.write!=b.write)return 8;if(b.write&&b.addr==0x60000e)++writes;}events+=x.n;++phases;}if(c->getPC()!=0x7000)return 9;++graphs;}if(writes<graphs)return 10;std::printf("{\"passed\":true,\"graphs\":%llu,\"phases\":%llu,\"events\":%llu,\"short_budgets\":%llu,\"dsp_writes\":%llu}\n",(unsigned long long)graphs,(unsigned long long)phases,(unsigned long long)events,(unsigned long long)shorts,(unsigned long long)writes);}
